		"content": "Dove ti nascondesti, amato canto spirituale (San Giovanni della Croce) dove ti nascondesti, amato, e mi lasciasti gemere? Sei fuggito come un cervo, dopo avermi ferito; Ti sono uscito dietro, piangendo, e tu non c'eri più. Pastori, voi che andate là, per gli ovili, sul colle, se per caso vedete colui che amo di più, ditegli che soffro, soffro e muoio. Cercando i miei amori, andrò per quei monti e quelle rive di fiumi; Non coglierò fiori, non temerò le fiere e attraverserò fortezze e confini. Oh foreste e boschetti, piantati dalla mano dell'amato! Oh prato d'ortaggi, di fiori smaltati, decidi se ti è passato! effondendo mille grazie, passò in fretta per questi boschetti, e guardandoli, con la sola figura vestita, li lasciò con la sua bellezza. Oh, chi può guarirmi! ti ha appena dato la verità; Non vogliono mandarmi un altro messaggero oggi, non sanno dirmi cosa voglio. OH! OH! mille grazie sparse dove ti nascondevi, amato",
