		"content": "Presso i canali di Babilonia: Salmo 137 (136): Ricordandoti, ci sediamo a piangere. Le chitarre pendevano dai salici, ricordandoci di te ci siamo seduti a piangere. \"Cantate per noi\", ci hanno detto i nostri nemici. \"Cantate per noi\", ci hanno detto i nostri oppressori. Volevano che li intrattenessimo. Come cantare una canzone del Signore in una terra straniera? Se ti dimentico, possa la mia mano destra seccarsi. La mia lingua si attacchi al palato, se ti dimentico, Gerusalemme, nel colmo della mia gioia. Signore, prendi in considerazione i nostri nemici. Signore, ritieni responsabili i nostri oppressori. quando si dissero: rase al suolo fino alle fondamenta! capitale della criminale Babilonia, chi potrebbe ricompensarti dei mali che ci hai fatto? Chi potrebbe sbattere i tuoi figli contro la pietra? dai canali babilonesicriminali",
