		"content": "balaam nm 23,7-24 da aram balaq, il re di Moab, mi ha chiamato a venire dai monti dell'oriente: «vieni e maledici Giacobbe; Venite e profetizzate contro Israele. Come posso maledire se Dio non vuole? Come profetizzerò se Dio non me lo permette? Dall'alto di questa vetta vedo, dall'alto di questa roccia contemplo: questo è un popolo diverso da tutte le nazioni. Quanto sono belle le tue tende, quanto sono belle, Israele! Quanto sono belle le tue tende, quanto sono belle, Israele! chi conterà, conterà la tua moltitudine? Giacobbe, Giacobbe, Giacobbe, Giacobbe. Lascia che sia, lascia che la mia morte sia come la morte del suo giusto. La mia vita va a lui, la mia vita va a lui. Quanto sono belli i tuoi negozi, ma cosa stai facendo? lo stai benedicendo! Vieni, forse da qualche altra parte Dio vuole maledirlo. Ascolta, figlio di Sippor, ascolta, re Balaq; che Dio non è un uomo che dice e si pente. Una stella sorge da Giacobbe, si odono acclamazioni per il loro re. Dio è tuo padre. \"Si sdraia come un leone, si sdraia come una leonessa, nessuno lo farà alzare.\" quanto sono belli i tuoi negozi di Balaam",
