		"content": "Mentre dormivo, canta i Cantici 5:2ss. Mentre dormivo e il mio cuore era sveglio, ho sentito la voce della mia amata: \"Aprimi, sorella mia, aprimi, colomba, perché la mia testa è coperta di rugiada e i miei capelli di rugiada notturna\". Ha infilato la mano nel buco della serratura e ho tremato tutta. Corsi su e le mie mani gocciolavano mirra, le mie dita scorrevano attraverso la serratura della porta. Vi scongiuro, figlie di Gerusalemme, se trovate il mio amato, ditegli che muoio d'amore. Ho aperto, ho aperto al mio amato, ma lui non c'era, era già passato. e l'anima mia fuggì da me nella sua fuga. L'ho cercato, non l'ho trovato, l'ho chiamato, l'ho chiamato e non mi ha risposto. Le guardie che facevano il giro mi hanno trovato, mi hanno picchiato, le guardie sui muri mi hanno spogliato nudo. Ti evoco, oh, se fossi mio fratello, potrei baciarti quando ti trovo alla porta! Ti evoco... mentre dormivo",
