		"content": "elí, elí, lamá sabactaní 63 sale 22 (21) elí, elí, lamá sabactaní. Dio mio, Dio mio, perché mi hai abbandonato? Quanto ti sento lontano dalle mie urla! Piango di giorno e non rispondi, piango di notte e non ho riposo. elí, elí, lamá sabactaní ma tu sei il santo, tu che vivi in ​​mezzo al mio popolo! I nostri padri ti hanno gridato e tu li hai aiutati, si sono fidati di te e non si sono mai confusi. Allora perché non mi aiuti? Non sono un uomo? Questo sono io: sono un verme, il disprezzo della gente, il disgusto della gente, tutti quelli che mi vedono ridono, scuotono la testa e dicono: \"Si è affidato a Dio, lo salvi, lo salvi, se dice che lo ama tanto!\" sì, che mi ami, sì, che mi ami, nel grembo di mia madre mi hai formato; Quando mi ha dato alla luce già mi ha offerto a te, fin dal grembo di mia madre eri già il mio Dio. elí, elí, lamá sabactaní Sono acqua sporca che si butta via, tutte le mie ossa si slogano come cera il mio cuore, si scioglie nelle mie viscere. Il mio palato è secco come una pietra e la lingua è incollata alla gola. elí, elí, lamá sabactaní mi circondano innumerevoli cani, mi assale una banda di malfattori, mi forano le mani e i piedi. puoi contare le mie ossa; Mi osservano e mi guardano, distribuiscono i miei vestiti, mettono in palio la mia tunica. ma tu, mio ​​Dio, non essere lontano! Vieni in mio aiuto, mia forza, libera l'anima mia dalla spada, libera la mia vita dalle fauci del leone, libera l'anima mia dalle corna del bufalo. Annuncerò il tuo nome ai miei fratelli, in mezzo all'assemblea ti canterò!: \"Tu che ami il Signore, lodalo, razza di Giacobbe, glorifica il Signore, temilo, popolo d'Israele\". perché è stato l'unico che non ha avuto disgusto di questo povero né ha disdegnato la miseria della mia vita; Non mi ha nascosto il suo volto quando l'ho invocato, perciò ora so che i poveri vivranno. I poveri mangeranno, saranno saziati, chi cerca Yahweh lo troverà: il suo cuore, il suo cuore, vivrà in eterno! elielilamasabactani",
		"translated": true
