		"content": "Gesù girava per tutte le città 95 Gesù girava per tutte le città. Gesù annunciava il regno di città in città. E vedendo la gente che lo seguiva, si commosse. Erano stanchi, erano abbattuti come pecore senza pastore. Allora Gesù disse ai suoi discepoli: \"La messe è molta, è veramente grande, e gli operai sono pochi. Pregate, fratelli, il padrone della messe che mandi operai nella sua messe. Ecco, io vi mando come pecore in mezzo ai lupi. siate prudenti come serpenti e semplici come colombe, come colombe. mt 9,35ss; 10 Non portate borsa, né denaro, né bisaccia, né scarpe. e annunciate che il regno è vicino, Cristo è risorto e viene con noi, viene con noi. Chi ama suo padre o sua madre più di me non è degno di me, non è degno di me. Chi ama suo figlio o sua figlia più di me non è degno di me, chi non prende la sua croce e non mi segue, non è degno di me, perché chi cerca la sua vita in questo mondo, la perderà e chi perderà la sua vita per amore mio, la troverà. lo troverà. Chi ascolta voi, ascolta me. Chi accoglie voi, accoglie me. Chi accoglie me, accoglie Dio. Gesù girava per tutte le città",
