		"content": "misericordia, mio ​​Dio, per la tua bontà, per la tua immensa compassione cancella la mia colpa. Lava completamente il mio crimine, purifica il mio peccato. Ebbene, riconosco la mia colpa, tengo sempre presente il mio peccato: contro te, contro te solo, ho peccato, ho commesso il male che tu odi. Nella sentenza avrai ragione, nel processo sarai innocente. Ecco, sono nato nella colpa, mia madre mi ha concepito peccatore. Ti piace un cuore sincero e infondi saggezza dentro di me. cospargimi di issopo: sarò puro; Lavami: sarò più bianco della neve. Fammi sentire la gioia e la felicità, possano esultare le ossa rotte. Distogli lo sguardo dal mio peccato, cancella da me ogni colpa. O Dio, crea in me un cuore puro, rinnovami dentro con spirito saldo; non respingermi dal tuo volto, non privarmi del tuo santo spirito. Ridammi la gioia della tua salvezza, rafforzami con animo generoso; Insegnerò agli empi le tue vie, a te ritorneranno i peccatori. Liberami dal sangue, o Dio, Dio, mio ​​Salvatore, e la mia lingua canterà la tua giustizia. Signore, aprirai le mie labbra e la mia bocca proclamerà la tua lode. i sacrifici non ti soddisfano: se ti offrissi un olocausto, non lo vorresti. il mio sacrificio è uno spirito spezzato; un cuore spezzato e umiliato, non lo disprezzi. Signore, nella tua bontà, favorisci Sion, ricostruisci le mura di Gerusalemme: allora accetterai i sacrifici rituali, le offerte e gli olocausti, saranno immolati tori sul tuo altare. misericordiadio",
