		"content": "preghiera eucaristica ii: modello ii (1987): il Signore sia con voi.e con il tuo spirito.solleviamo i nostri cuori.Lo abbiamo innalzato al Signore.Rendiamo grazie al Signore, nostro Dio. È giusto e necessario.Davvero è giusto e necessario, è nostro dovere e fonte di salvezza renderti grazie, sempre e ovunque.A te, santo padre, per Gesù Cristo, tuo figlio amatissimo.Per mezzo di lui, che è la tua parola vivente, hai fatto tutte le cose;Tu ce lo hai mandato, salvatore e redentore, fatto uomo per opera dello Spirito Santo e nato da Maria Vergine, per compiere la tua volontà e acquisirti un popolo santo.Ha steso le braccia sulla croce, morendo ha distrutto la morte.e annunciò la risurrezione.e annunciò la risurrezione.Per questo mistero di salvezza, uniti agli angeli e ai santi cantiamo ad una sola voce l'inno della tua gloria: santo, santo, santo santo sei veramente, Signore, fonte di ogni santità: epiclesi.la preghiera di consacrazione santifica questi doni con l'effusione del tuo spirito, affinché siano per noi il corpo e il sangue di Gesù Cristo, nostro Signore.conto dell'istituzione che, quando stava per essere consegnato alla sua passione, accettò volontariamente, prese il pane, rendendo grazie a voi, lo spezzò e lo diede ai suoi discepoli, dicendo: Prendetelo tutti e mangiatene, perché questo è il mio corpo, che sarà dato per voi.Allo stesso modo, terminato il pasto, prese il calice e, ringraziando ancora, lo passò ai suoi discepoli, dicendo: prendetelo tutti e bevetene, questo è il calice del mio sangue, sangue della nuova ed eterna alleanza, che sarà versato per voi e per molti, in remissione dei peccati.Fate questo in memoria di me.acclamazione questo è il sacramento della nostra fede.Annunciamo la tua morte, Signore, proclamiamo la tua risurrezione, vieni, Signore Gesù!vieni, Signore Gesù!Perciò, padre, mentre celebriamo ora il memoriale della morte e della risurrezione del tuo Figlio, ti offriamo il pane della vita e il calice della salvezza, e ti ringraziamo perché ci rendi degni di servirti alla tua presenza.epiclesi chiediamo umilmente che lo Spirito Santo riunisca nell'unità tutti noi che partecipiamo al corpo e al sangue di Cristo.intercessioni, ricordati, Signore, della tua Chiesa diffusa su tutta la terra;e col papa n/, col nostro vescovo n/.e tra tutti coloro che in esso si prendono cura del tuo popolo, portalo alla sua perfezione mediante la carità.ricordati anche dei nostri fratelli che dormivano nella speranza della risurrezione, e di tutti coloro che sono morti nella tua misericordia;Ammettili di contemplare la luce del tuo volto.memoria dei santi abbi pietà di tutti noi, e così, con Maria, la vergine madre di Dio, suo sposo san Giuseppe, gli apostoli e tutti coloro che hanno vissuto nella tua amicizia attraverso i secoli, meritiamo, attraverso tuo figlio Gesù Cristo, di condividere la vita eterna e di cantare le tue lodi.dossologia e conclusione della preghiera eucaristica per Cristo, con Cristo e in Cristo, a te, Dio Padre onnipotente, nell'unità dello Spirito Santo, ogni onore e ogni gloria nei secoli dei secoli.amen, amen, amen.Preghiera eucharisticprayeriimodelii, Prefazio",
