		"content": "L'annuncio pasquale esulta i cori degli angeli, esulta l'assemblea celeste e un inno di gloria acclama il trionfo del Signore risorto. Gioisca la terra, inondata dalla nuova luce. Lo splendore del re ha distrutto le tenebre, ha distrutto le tenebre, le tenebre del mondo. Si rallegri la Chiesa nostra madre, risplendente della gloria del suo Signore; e che in questo luogo risuona unanime l'acclamazione di un popolo in festa. il Signore sia con te. al e con il tuo spirito. solleviamo i nostri cuori. Lo abbiamo innalzato al Signore. Rendiamo grazie al Signore, nostro Dio. È giusto e necessario. È veramente giusto e necessario esaltare con il canto la gioia dello spirito ed elevare un inno al Padre onnipotente, e al suo unico Figlio, Gesù Cristo. Egli ha saldato per tutto il debito di Adamo verso l'eterno Padre e, con il suo sangue, versato per amore, ha cancellato l'antica condanna del peccato. Questa è la Pasqua, nella quale viene sacrificato l'agnello. Questa è la notte in cui i nostri padri furono liberati dall'Egitto. Questa è la notte che ci salva dalle tenebre del male. Questa è la notte in cui Cristo ha sconfitto la morte e ritorna vittorioso dall'inferno. oh ammirabile condiscendenza del tuo amore! Oh tenerezza e carità incomparabili! Per salvare lo schiavo hai sacrificato il figlio. Senza il peccato di Adamo, Cristo non ci avrebbe salvato. oh felice colpa che meritò un così grande redentore! oh felice colpa! Oh meravigliosa notte in cui hai spogliato il Faraone e hai arricchito Israele! o notte meravigliosa, tu sola hai conosciuto l'ora in cui Cristo è risorto! oh notte che distruggi il peccato e lava ogni nostra colpa! oh notte veramente gloriosa che riconcili l'uomo col suo Dio! Questa è la notte in cui Cristo ha sconfitto la morte e ritorna vittorioso dall'inferno. Accetta in questa notte, Padre santo, questo sacrificio di lode che la Chiesa ti offre attraverso i suoi ministri nella solenne liturgia di questo cero, che è il segno della nuova luce. Ti preghiamo, Signore, affinché questa candela offerta in onore del tuo nome risplenda luminosa; Ti arriva, come un profumo soave, si fonde con le stelle del cielo. La trova accesa la stella del mattino, quella stella che non conosce il tramontare. perché Cristo è tuo figlio, risorto, risorto dai morti. amen, amen, amen. pregonpascual",
