		"content": "salmodie per lodi salmodie!sale 64 (63) ogni mortale viene a te a causa dei suoi peccati;I nostri crimini ci sopraffanno, ma tu li perdoni.salmodia ii è 38 solleva e avvolgi la mia vita come la tenda di un pastore.Come un tessitore, stavo tessendo la mia vita, e loro hanno tagliato la trama.giorno e notte mi finisci, singhiozzo fino all'alba.Mi spezzi le ossa come un leone, giorno e notte mi distruggi.salmodia iii sale 43 (42) tu sei il mio Dio e protettore, perché mi respingi? Perché vado in giro cupo, infastidito dal mio nemico?salmodia iv dt32 Ascolta, cieli, e io parlerò, ascolta, terra, le parole della mia bocca: scenda come pioggia la mia dottrina, distilli come rugiada la mia parola.salmodia v sale 46 (45) Dio è il nostro rifugio e la nostra forza, difensore potente nel pericolo.Per questo non abbiamo paura, anche se la terra trema e le montagne crollano nel mare.ribollino e ruggiscano le sue onde, scuotano i monti con la loro furia.Il Signore degli eserciti è con noi, nostra fortezza è il Dio di Giacobbe.Lo scorrere delle rogge esulta la città di Dio, l'Altissimo consacra la sua dimora.avendo Dio al centro, non esita;Dio li aiuta all'alba.salmodia vi sale 49 (48) con la melodia di •il signore annuncia notizie•.la mia bocca parlerà saggiamente;e le mie riflessioni saranno molto sensate;Ascolterò il proverbio e proporrò il mio problema al suono della cetra.salmodia vii ap 11 ti rendiamo grazie, Signore Dio onnipotente, che sei e che eri, perché hai assunto un grande potere, e hai cominciato a regnare.Ora la salute e la potenza sono stabili, così come il regno del nostro Dio e la potenza del suo Cristo.salmodia viii sale 96 (95) il Signore regna, esulta la terra, esultano le innumerevoli isole.tenebre e nubi lo avvolgono, giustizia e diritto sostengono il suo trono.Il fuoco avanza davanti a lui, bruciando tutt'intorno i nemici;I suoi fulmini abbagliano il mondo e, vedendolo, la terra trema.salmodia ix sal 149 Cantate al Signore un canto nuovo, risuoni la sua lode nell'assemblea dei fedeli.Gioisca Israele per il suo creatore, i figli di Sion per il loro re.lodate il suo nome con danze, cantategli con tamburi e cetre;perché il Signore ama il suo popolo e adorna di vittoria gli umili.salmodia x sb 9 Dio dei padri e Signore di misericordia, con la tua parola hai fatto tutte le cose, e con sapienza hai formato l'uomo, affinché regnasse sulle tue creature.salmodieperlaudi",
