		"content": "Signore, non correggermi nella tua ira: Salmo 6: Signore, non correggermi nella tua ira, non punirmi nel tuo furore.Abbi pietà di me, abbi pietà Signore, sono senza forze, guariscimi Signore, le mie ossa si sbriciolano.La mia anima è affondata, e tu, Signore, fino a quando?E lei, signore, fino a quando?Signore, non correggermi, ritorna, Signore, guarisci la mia anima, guariscimi, Signore, con la tua misericordia.che nessuno tra i morti si ricorda di te, né si canta la tua lode nell'inferno.che nessuno tra i morti si ricorda di te, né si canta la tua lode nell'inferno.Signore, non correggermi, sono stanco di gemere, inondo di lacrime il mio letto, i miei occhi sono consumati dall'angoscia, invecchio tra i nemici.Allontanatevi da me, malvagi, perché il Signore ascolta i miei singhiozzi e il Signore accoglie la mia preghiera.signore, non corregga me e lei, signore, fino a quando?E lei, signore, fino a quando?Sirome corregge la tua rabbia",
