		"content": "Se oggi ascolti la sua voce: Salmo 95 (94): Se oggi ascolti la sua voce, non indurire il tuo cuore.Venite, acclamiamo al Signore, esultiamo per la roccia che ci salva;Entriamo alla sua presenza ringraziandolo, acclamandolo con canti e salmi.Se oggi ascolti la sua voce perché il Signore è un Dio grande, più grande di tutti gli Dei;Suo è il mare, sua la terra, sue le vette.Se oggi senti la sua voce, entra, prostriamoci a terra, benedicendo il Signore, nostro creatore.poiché egli è il nostro Dio e noi siamo il suo popolo, il gregge che egli guida.Se sentite la sua voce oggi, lo spero!Spero che sentirete la sua voce oggi e non indurite i vostri cuori!come a Meribah, come nel giorno del massah nel deserto, dove i tuoi padri dubitarono di me, benché avessero visto le mie opere mi costrinsero a fare la loro volontà.Per quarant'anni quella generazione non mi è piaciuta.e io ho detto: \"questo è un popolo dal cuore perduto, non vuole conoscere le mie vie, per questo non entrerà nel mio riposo\".Se oggi ascolti la sua voce, se oggi ascolti la sua voce",
