		"content": "Ti ho rivelato il mio peccato: Salmo 32 (31): Ti ho rivelato il mio peccato, non ho tenuto nascosti i miei errori.Ho detto: \"Confesserò la mia colpa al Signore\".e tu hai perdonato la malizia del mio peccato.Beato l'uomo i cui peccati sono perdonati e i suoi peccati sono coperti.Beato l'uomo a cui il Signore non imputa alcun male e nel cui spirito non c'è inganno.Ti ho manifestato il mio peccato, ho taciuto e le mie ossa si sono consumate, gemendo tutto il giorno, perché giorno e notte pesava su di me la tua mano, come un'estate il mio cuore era arido.Ma io ti ho rivelato il mio peccato, non ho tenuto nascosti i miei errori, ho detto: «Confesserò al Signore la mia colpa».e tu hai perdonato la malizia del mio peccato.Ti ho manifestato il mio peccato, per questo i tuoi fedeli ti pregano nel giorno della sventura, quando le grandi acque strariperanno, ma non lo raggiungeranno.Tu sei il mio rifugio, mi preservi dal pericolo, mi circondi di canti di salvezza, mi dici: \"Ti farò saggio, ti indicherò la via della vita\".Ti ho manifestato il mio peccato. Ti ho manifestato il mio peccato",
