		"content": "Un germoglio spunta dal tronco di Iesse: Isaia 11,1-11: Un germoglio spunta dal tronco di Iesse, un germe dalle sue radici.Su di lui riposa lo spirito del Signore: spirito di sapienza e di intelligenza, spirito di consiglio e di forza, spirito di scienza e di pietà, spirito di timore del Signore.Non giudicherà per sentito dire, ma aiuterà gli oppressi.La sua parola sarà una verga contro i violenti e con il soffio della sua bocca ucciderà gli empi.Il lupo abiterà con l'agnello, la pantera giacerà con la capra, il leone e il toro pascoleranno insieme, e un bambino li condurrà, e un bambino li guiderà.germoglierà un germoglio, la mucca e l'orso saranno insieme, il leone, come il bue, mangerà la paglia.Il lattante si addentrerà nella tana dell'aspide, il neonato metterà la mano nella tana della vipera.perché nessuno farà più male.perché nessuno farà più male.poiché la terra sarà piena della conoscenza del Signore.poiché la terra sarà piena della conoscenza del Signore.Perché in quel giorno la radice di Iesse sarà innalzata come vessillo del popolo, e il popolo lo seguirà con entusiasmo.In quel giorno il Signore stenderà la mano e si formerà una via, e si formerà una via;una via per tutte le nazioni, una via per tutte le nazioni;che la vergine indicherà.dal tronco scaturisce un ritorno",
