		"content": "vieni dal Libano: cantico dei cantici 4,8ss: vieni dal Libano, moglie, vieni dal Libano, vieni.Avrai per corona la cima dei monti, l'alta vetta dell'Ermon.mi hai ferito, ferito il mio cuore, oh moglie, mia amata.Vieni dal Libano, moglie, vieni dal Libano, vieni.Ho cercato l'amore della mia anima, l'ho cercato senza trovarlo.Ho trovato l'amore della mia vita, l'ho abbracciato e non lo lascerò mai.Appartengo al mio amato e lui è tutto per me.Vieni, andiamo nei campi, ci perderemo nei paesi.Usciremo all'alba verso le vigne e ne raccoglieremo il frutto.Appartengo al mio amato e lui è tutto per me.Cercavo l'amore dell'anima mia, alzati presto, mia amata, vieni, colomba, vieni.perché l'inverno è già passato, già si sente il canto dell'allodola.I fiori appaiono sulla terra, è arrivato il sole forte.Alzati presto, mio ​​diletto, vieni, colomba, vieni.Ho cercato l'amore della mia anima come un sigillo sul mio cuore, come un tatuaggio sul mio braccio.L'amore è forte come la morte, le acque non lo spegneranno.dare tutti i beni della casa per questo amore sarebbe disprezzarlo.come un sigillo sul cuore, come un tatuaggio sul braccio.Cercavo l'amore dell'anima mia, vendellibano",
