		"content": "vieni, spirito santo: Sequenza di Pentecoste - Inno latino “veni, sancte spiritus”: vieni, spirito santo, manda un raggio della tua luce vieni, padre dei poveri, vieni, luce del cuore.Vieni, ottimo consolatore, dolce ospite dell'anima.Vieni, dolce ristoro, nella fatica sei riposo.Con il caldo sei il nostro sollievo.Nel piangere sei conforto.O luce benedetta, inonda con il tuo fulgore l'intimo dei cuori dei tuoi fedeli, raggiungi le profondità dell'anima, senza la tua luce non c'è nulla di puro nell'uomo, non c'è nulla di innocente.Guarda la forza del peccato quando non sei con noi.lava ciò che è sporco, annaffia ciò che è asciutto.Egli guarisce ciò che è malato, converte i duri e i rigidi.Infiamma ciò che è tiepido, guida gli smarriti.Donaci i tuoi sette doni, donaci il tuo amore e la tua gioia.donaci virtù e ricompensa, donaci la gioia della salvezza.Donaci una morte santa, donaci la gioia eterna, donaci sapienza e intelligenza, donaci scienza e pietà.donaci consiglio e forza, donaci il timore di Dio. Donaci i tuoi santi frutti, donaci pazienza e bontà.Donaci amore e gioia, donaci giustizia e verità.vienispiritosanto",
